import{_ as n}from"./chunks/16.BNYXiHW-.js";import{_ as r}from"./chunks/image3.DoZHhKNh.js";import{_ as a}from"./chunks/image3.BcCRCwOU.js";import{_ as s}from"./chunks/image.mtVmn3vQ.js";import{_ as l}from"./chunks/image1.CcZc1vrM.js";import{_ as e}from"./chunks/image.W_Wbo9Z-.js";import{_ as d}from"./chunks/image3.B-7DYkmr.js";import{_ as c}from"./chunks/image4.Ca1pzk-J.js";import{_ as h}from"./chunks/image8.2GLaHkOt.js";import{_ as p}from"./chunks/image.BZc8PBVN.js";import{_ as g}from"./chunks/100.DC6t8P7m.js";import{_ as m}from"./chunks/community.CGfILmM2.js";import{_ as u,C as b,o as y,c as _,ak as o,E as f}from"./chunks/framework.CaWw1yIg.js";const v="/projects/AiBlock/en/standard-kit/assets/1.BDBSgrFt.webp",w="/projects/AiBlock/en/standard-kit/assets/image10.DB0u9Uem.webp",k="/projects/AiBlock/en/standard-kit/assets/4.C8uAZoXw.webp",x="/projects/AiBlock/en/standard-kit/assets/2.DJDrPOlO.webp",P="/projects/AiBlock/en/standard-kit/assets/5.B_qJvMZd.webp",C="/projects/AiBlock/en/standard-kit/assets/3.Bf6WGcZp.webp",$=JSON.parse('{"title":"3.16 Rotary Conveyor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Creative Builds/3.16 Rotary Conveyor.md","filePath":"docs/3. Creative Builds/3.16 Rotary Conveyor.md"}'),q={name:"docs/3. Creative Builds/3.16 Rotary Conveyor.md"};function S(j,t,A,T,z,B){const i=b("Pdf");return y(),_("div",null,[t[0]||(t[0]=o('<h1 id="_3-16-rotary-conveyor" tabindex="-1">3.16 Rotary Conveyor <a class="header-anchor" href="#_3-16-rotary-conveyor" aria-label="Permalink to &quot;3.16 Rotary Conveyor&quot;">​</a></h1><h2 id="_3-16-1-lesson-introduction" tabindex="-1">3.16.1 Lesson Introduction <a class="header-anchor" href="#_3-16-1-lesson-introduction" aria-label="Permalink to &quot;3.16.1 Lesson Introduction&quot;">​</a></h2><p>Taking inspiration from industrial assembly lines, this lesson guides the assembly of an automated conveyor and sorting system combining continuous track transmission with servo-driven chute sorting. The lesson explains track transmission mechanics alongside cooperative control across three components, dividing roles such that the motor powers the conveyor, the servo directs the sorting chute, and the knob provides stepless position adjustments. This lesson provides an introduction to track drives and wraps up starter builds, establishing system-level conveyance-and-sorting thinking for sophisticated automation engineering.</p><img loading="lazy" height="1662" width="1662" src="'+n+'" class="common_img" style="width:400px;"><h2 id="_3-16-2-learning-objectives" tabindex="-1">3.16.2 Learning Objectives <a class="header-anchor" href="#_3-16-2-learning-objectives" aria-label="Permalink to &quot;3.16.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand continuous track drive principles and positive gear engagement. Master the decoupled design between conveyance and sorting mechanisms. Consolidate programming techniques for knob analog values. Strengthen cooperative programming across multiple actuators.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the continuous track conveyor and directional sorting chute independently. Execute accurate hardware wiring and servo centering calibration. Program coordinated conveyance and sorting routines. Master stepless angle tuning techniques using the knob module.</p></li><li><p><strong>Thinking Objectives</strong>: Build systems engineering thinking integrating conveyance with automated sorting. Cultivate awareness of multi-mechanism task allocation. Understand the functional distinction between stepless adjustment and discrete preset stepped switching. Strengthen multi-device coordinated programming logic.</p></li><li><p><strong>Application Objectives</strong>: Connect concepts to industrial manufacturing lines, supermarket checkout belts, parcel sorting hubs, and tank treads. Recognize the engineering significance of automated assembly lines. Stimulate curiosity regarding industrial automation and mechanical powertrains.</p></li></ol><h2 id="_3-16-3-preparation" tabindex="-1">3.16.3 Preparation <a class="header-anchor" href="#_3-16-3-preparation" aria-label="Permalink to &quot;3.16.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>360° block motor</p></li><li><p>180° block servo</p></li><li><p>Knob module</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab Graphical Programming Platform</li></ul><h2 id="_3-16-4-hands-on-project" tabindex="-1">3.16.4 Hands-On Project <a class="header-anchor" href="#_3-16-4-hands-on-project" aria-label="Permalink to &quot;3.16.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the knob-controlled sorting Rotary Conveyor, simulating a modern manufacturing conveyor where a continuous track transports items and an exit guide chute sorts them into left and right collection bins. The conveyance assembly uses a motor driving geared tracks for steady transport, while the sorting assembly employs a servo to orient the guide chute. The foundational version implements two-position stepped sorting via buttons, setting 0° for the left bin on a left button press and 90° for the right bin on a right button press. The optimized version incorporates the knob for stepless angle adjustment, allowing flexible aiming. The software halts conveyance momentarily while steering the chute to prevent parcels from veering off-track, resuming belt motion once aligned. This project synthesizes structural mechanics and nested conditional logic across multiple actuators.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),f(i,{src:"../../_static/shared/pdf/chapter_3/16.pdf"}),t[1]||(t[1]=o('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 180° block servo to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the 360° block motor to port <strong>S2</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the knob module to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1156" width="2043" src="'+v+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Knob</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+r+'" class="common_img" style="width:800px;"><ul><li>Select <strong>180° servo</strong> and <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+a+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="164" width="359" src="'+w+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+s+'"></td><td style="text-align:left;">Checks whether the left or right button on the controller is pressed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="148" width="624" src="'+l+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+e+'"></td><td style="text-align:left;">Sets the operating speed and rotation direction of the designated motor</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="64" width="358" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+e+'"></td><td style="text-align:left;">Stops the motor connected to the selected port</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="65" width="625" src="'+c+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+e+'"></td><td style="text-align:left;">Controls the designated servo to rotate to a target angle at a specified speed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="48" width="424" src="'+h+'"></td><td style="text-align:center;"><img loading="lazy" height="80" width="99" src="'+p+'"></td><td style="text-align:left;">Reads the numerical value of the knob module on the specified port, ranging from 0 to 100</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li><p>Case 1: Button-Triggered Discrete Servo Control</p><ul><li>Program Schematic</li></ul><img loading="lazy" height="720" width="430" src="'+k+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>Executing the main program initiates a continuous loop that polls button states:</p><ul><li><p>When the left button is pressed, motor S2 stops rotating and servo S1 rotates to 0° at 30% speed without delay.</p></li><li><p>When the left button is released and the right button is pressed, motor S2 stops rotating and servo S1 rotates to 90° at 30% speed without delay.</p></li><li><p>When neither button is pressed, motor S2 rotates in reverse at 10% speed.</p></li></ul></li></ul><img loading="lazy" height="557" width="676" src="'+x+'" class="common_img" style="width:500px;"></li><li><p>Case 2: Knob-Regulated Continuous Servo Adjustment</p><ul><li>Program Schematic</li></ul><img loading="lazy" height="451" width="430" src="'+P+'" class="common_img" style="width:400px;"><ul><li>Complete Program</li></ul><img loading="lazy" height="269" width="719" src="'+C+'" class="common_img" style="width:500px;"></li><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to upload the program to the controller and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+g+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1xyD_-3msc3KcaGQHLqkcPOZNSNXFIirT?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-16-5-expansion-and-challenge" tabindex="-1">3.16.5 Expansion and Challenge <a class="header-anchor" href="#_3-16-5-expansion-and-challenge" aria-label="Permalink to &quot;3.16.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Three-Way Intelligent Sorting System</strong></p><p>Add a center collection bin to implement left, center, and right three-way sorting. Pressing the left button routes items to the left, pressing the right button routes items to the right, and leaving buttons untouched routes items to the center by default. Practice three-branch conditional evaluation and multi-position control, upgrading two-way sorting into a multi-port industrial sorter.</p><p><strong>Project 2: Automated Counting Conveyor Line</strong></p><p>Incorporate an ultrasonic or light sensor to detect passing items, incrementing a count by 1 each time an object passes. Use a variable to track the total count and sound the buzzer upon each detection. Practice variable counting and sensor-driven tallying to transform a simple conveyor into an automated assembly line with production statistics.</p><h2 id="_3-16-6-q-a" tabindex="-1">3.16.6 Q&amp;A <a class="header-anchor" href="#_3-16-6-q-a" aria-label="Permalink to &quot;3.16.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Why does the motor halt before the servo turns the chute, rather than rotating the chute while the conveyor runs?</strong></p><p>Answer: Halting the motor prevents transported items from misaligning or falling off the belt. If the conveyor track continues moving while the chute swings abruptly, items risk tumbling outward due to momentum or snagging on the chute rims, degrading sorting precision. Halting the track before redirecting the chute ensures items slide securely into the proper collection bin once re-engaged. In industrial parcel sorters, items are similarly registered and aligned before mechanical diverters engage. In engineering design, pause-before-switching routines prioritize physical stability and operational repeatability.</p><p><strong>Question 2: What is the distinction between knob control and button control for steering, and what are their respective benefits?</strong></p><p>Answer: Button control is <strong>stepped or discrete</strong>, offering a limited set of fixed presets, such as 0° and 90°. Pressing a button toggles between predetermined positions, making operation simple and fast, though restricted to preset targets. Knob control is <strong>stepless or continuous</strong>, covering any angle between 0° and 100°. Rotating the knob positions the chute precisely to any orientation, providing fine-grained alignment with variously positioned collection bins. Discrete stepped control offers effortless single-press operation suited for standardized, fixed-pattern sorting. Stepless control delivers adaptable precision required for custom, dynamic alignments. Industrial machinery frequently employs both modalities based on operational demands.</p><h2 id="_3-16-7-technical-support-and-product-discussion" tabindex="-1">3.16.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-16-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.16.7 Technical Support and Product Discussion&quot;">​</a></h2><p>To share creative ideas and projects after exploring this kit, visit the Hiwonder Community:</p><a href="https://forum.hiwonder.com/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+m+'" class="common_img" style="width:800px;"></a>',27))])}const G=u(q,[["render",S]]);export{$ as __pageData,G as default};
